static void fail ( struct test * test , struct sg_table * st , const char * cond ) { int i ; fprintf ( stderr , "Failed on '%s'!\n\n" , cond ) ; printf ( "size = %u, max segment = %u, expected nents = %u\nst->nents = %u, st->orig_nents= %u\n" , test -> size , test -> max_seg , test -> expected_segments , st -> nents , st -> orig_nents ) ; printf ( "%u input PFNs:" , test -> num_pages ) ; for ( i = 0 ; i < test -> num_pages ; i ++ ) { printf ( " %x" , test -> pfn [ i ] ) ; } printf ( "\n" ) ; exit ( 1 ) ; } 